import React from 'react';

const DonorCard = ({ donor, onClick }) => {
    // Define styling based on donor status
    let statusStyle = "";
    let statusBadge = "";
    let bgGradient = "";
    
    if (donor.status === 'pending') {
        statusStyle = "text-yellow-800 bg-yellow-100 border-yellow-200";
        statusBadge = "Pending";
        bgGradient = "from-yellow-50 to-amber-50";
    } else if (donor.status === 'sending') {
        statusStyle = "text-blue-800 bg-blue-100 border-blue-200";
        statusBadge = "Processing";
        bgGradient = "from-blue-50 to-cyan-50";
    } else {
        statusStyle = "text-green-800 bg-green-100 border-green-200";
        statusBadge = "Completed";
        bgGradient = "from-green-50 to-emerald-50";
    }

    // Define type style
    const typeStyle = donor.type === 'sheep'
        ? "text-sky-800 bg-sky-100 border-sky-200"
        : "text-purple-800 bg-purple-100 border-purple-200";
    
    const typeBadge = donor.type === 'sheep' ? "Sheep" : "Cow (1/7 share)";

    return (
        <div 
            className={`bg-gradient-to-r ${bgGradient} rounded-lg shadow-sm border-l-4 hover:shadow-md transition-all duration-200 cursor-pointer relative overflow-hidden p-4`}
            onClick={onClick}
        >
            <div className="flex flex-col md:flex-row justify-between">
                <div>
                    <h3 className="text-lg font-semibold">{donor.firstName} {donor.lastName}</h3>
                    <p className="text-sm text-gray-600">{donor.whatsappNumber}</p>
                    <div className="flex flex-wrap gap-2 mt-2">
                        <span className={`text-xs px-2 py-1 rounded-full border ${typeStyle}`}>
                            {typeBadge}
                        </span>
                        <span className={`text-xs px-2 py-1 rounded-full border ${statusStyle}`}>
                            {statusBadge}
                        </span>
                    </div>
                </div>
                <div className="mt-3 md:mt-0">
                    <p className="text-gray-700 font-medium">
                        {donor.price?.toLocaleString() || '0'} DA
                    </p>
                    <p className="text-xs text-gray-500">
                        {new Date(donor.createdAt).toLocaleDateString()}
                    </p>
                </div>
            </div>
            
            {/* Decorative background element */}
            <div className="absolute top-0 right-0 w-20 h-20 opacity-10">
                {donor.type === 'sheep' ? (
                    <span className="text-5xl">🐑</span>
                ) : (
                    <span className="text-5xl">🐄</span>
                )}
            </div>
        </div>
    );
};

export default DonorCard;
